class ParameterHandler:
    """Processes the parameters of a vertex.

    This class is responsible for turning a vertex's edges and template fields
    into a ready-to-use parameters dictionary. It is intentionally decoupled from
    the ``Vertex`` build lifecycle so it can be exercised in isolation.
    """

    def __init__(self, vertex: Vertex, storage_service: StorageService) -> None:
        self.vertex = vertex
        self.storage_service = storage_service
        # Only the dict-valued entries of the template describe fields.
        self.template_dict: dict[str, dict] = {
            key: value for key, value in vertex.data["node"]["template"].items() if isinstance(value, dict)
        }

    def process_edge_parameters(self, edges: list) -> dict:
        """Build the params contributed by the incoming edges.

        Iterates over the edges, skipping any that do not define a
        ``target_param``, and maps each ``target_param`` to the source vertex.
        """
        params: dict = {}
        for edge in edges:
            if not hasattr(edge, "target_param") or edge.target_param is None:
                continue
            param_key = edge.target_param
            if param_key in self.template_dict and edge.target_id == self.vertex.id:
                field = self.template_dict[param_key]
                if field.get("list"):
                    if param_key not in params:
                        params[param_key] = []
                    params[param_key].append(self.vertex.graph.get_vertex(edge.source_id))
                else:
                    params[param_key] = self.process_non_list_edge_param(field, edge)
            elif param_key in self.vertex.output_names:
                params[param_key] = self.vertex.graph.get_vertex(edge.source_id)
        return params

    def process_non_list_edge_param(self, field: dict, edge: Edge) -> Any:
        """Resolve the value of a non-list edge parameter.

        For empty or non-dict field values the source vertex is returned
        directly. For a single-entry dict value a new dict is returned that
        maps the existing key to the source vertex.
        """
        param_dict = field.get("value")
        if isinstance(param_dict, dict) and len(param_dict) == 1:
            return {key: self.vertex.graph.get_vertex(edge.source_id) for key in param_dict}
        return self.vertex.graph.get_vertex(edge.source_id)

    def process_file_field(self, field_name: str, field: dict, params: dict) -> dict:
        """Resolve a ``file`` field into a full path (or list of paths)."""
        if file_path := field.get("file_path"):
            try:
                full_path: str | list[str] = ""
                if field.get("list"):
                    full_path = []
                    if isinstance(file_path, str):
                        file_path = [file_path]
                    for p in file_path:
                        flow_id, file_name = os.path.split(p)
                        path = self.storage_service.build_full_path(flow_id, file_name)
                        full_path.append(path)
                else:
                    flow_id, file_name = os.path.split(file_path)
                    full_path = self.storage_service.build_full_path(flow_id, file_name)
            except ValueError as e:
                if "too many values to unpack" in str(e):
                    full_path = file_path
                else:
                    raise
            params[field_name] = full_path
        elif field.get("required"):
            field_display_name = field.get("display_name")
            logger.warning(
                f"File path not found for {field_display_name} in component {self.vertex.display_name}. "
                "Setting to None."
            )
            params[field_name] = None
        elif field.get("list"):
            params[field_name] = []
        else:
            params[field_name] = None
        return params

    def should_skip_field(self, field_name: str, field: dict, params: dict) -> bool:
        """Return whether a template field should be skipped during processing."""
        if field_name in params:
            return True
        if field_name == "_type":
            return True
        return not field.get("show")

    def handle_optional_field(self, field_name: str, field: dict, params: dict) -> None:
        """Apply the default for an optional field or drop it when unset."""
        if not field.get("required") and params.get(field_name) is None:
            if field.get("default"):
                params[field_name] = field.get("default")
            else:
                params.pop(field_name, None)

